CREATE TABLE IF NOT EXISTS bat_business_day_calendar (
 calendar_id VARCHAR(50) NOT NULL,business_date DATE NOT NULL,holiday_yn CHAR(1) NOT NULL DEFAULT 'N',
 business_day_yn CHAR(1) NOT NULL DEFAULT 'Y',description VARCHAR(500),created_by VARCHAR(100) NOT NULL DEFAULT 'BAT',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'BAT',
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 PRIMARY KEY(calendar_id,business_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
